-- Deities and Demigods Appendix 1 spell definitions used by its new domains.
-- The original 3.0 Rage and Undeath to Death are intentionally not inserted here: the official 3.5 accessory update directs games to use the revised Player's Handbook spells instead.
-- Greater Status is taken from the official 3.5 accessory update appended to the supplied source.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES
  ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0','Deities and Demigods (2002).',NULL,1,0,NULL),
  ('dd-3.5-update','deities-and-demigods-3-5-update','Deities and Demigods - D&D v.3.5 Accessory Update','DD 3.5 Update','Wizards of the Coast','dnd','3.5','Official 3.5 revision notes for Deities and Demigods.',NULL,1,0,NULL);

WITH desired(id,source_id,page,slug,name,summary,school_id,subschool,casting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,saving_throw_text,save,spell_resistance,spell_resistance_text) AS (VALUES
  ('dd-spell-armor-of-darkness','dd-3.0','216','armor-of-darkness','Armor of Darkness','Wrap the subject in concealing shadow, granting a scaling deflection bonus to AC, darkvision, bonuses against holy/good/light effects, and additional turn resistance for undead.','phb-spell-school-abjuration',NULL,'1 standard action','standard','Touch','Creature touched',NULL,NULL,'10 minutes/level','Will negates (harmless)','will','yes','Yes (harmless)'),
  ('dd-spell-blacklight','dd-3.0','216','blacklight','Blacklight','Create mobile or stationary supernatural darkness that blocks normal vision and darkvision while allowing the caster to see within it; it can counter or dispel light effects of equal or lower level.','phb-spell-school-evocation',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)',NULL,'20-ft.-radius emanation centered on a creature, object, or point in space',NULL,'1 round/level (D)','Will negates or none (object)',NULL,'conditional','Yes; no for qualifying unattended objects/points'),
  ('dd-spell-bolt-of-glory','dd-3.0','216','bolt-of-glory','Bolt of Glory','Fire a positive-energy ray whose damage varies by the target''s nature and plane, dealing its greatest damage to undead and evil outsiders.','phb-spell-school-evocation',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./level)',NULL,NULL,'Ray','Instantaneous','None',NULL,'yes','Yes'),
  ('dd-spell-bolts-of-bedevilment','dd-3.0','216','bolts-of-bedevilment','Bolts of Bedevilment','For the spell''s duration, launch one ray per round that can daze a living target for 1d3 rounds on a failed Will save.','phb-spell-school-enchantment',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Ray','1 round/level','Will negates','will','yes','Yes'),
  ('dd-spell-crown-of-glory','dd-3.0','216','crown-of-glory','Crown of Glory','Gain +4 enhancement to Charisma and radiate celestial authority that compels creatures below 8 HD to pay attention; hostile action requires a Will save and the caster can issue limited suggestions during the effect.','phb-spell-school-evocation',NULL,'1 full-round action','full_round','Personal','You','120-ft.-radius emanation centered on you',NULL,'1 minute/level','Will negates','will','yes','Yes'),
  ('dd-spell-genesis','dd-3.0','216-217','genesis','Genesis','Create a small demiplane on the Ethereal Plane, determine its basic environment, and expand it with later castings; the spell cannot create life or constructed structures.','phb-spell-school-conjuration','Creation','1 week (8 hours/day)','other','180 ft.',NULL,NULL,'A demiplane on the Ethereal Plane centered on your location','Instantaneous','None',NULL,'no','No'),
  ('dd-spell-hardening','dd-3.0','217','hardening','Hardening','Increase an object''s material hardness by +1 per two caster levels without changing hit points or other properties; metal/mineral volume is more restricted.','phb-spell-school-transmutation',NULL,'1 standard action','standard','Touch','One item, up to 10 cu. ft./level; metal or mineral up to 1 cu. ft./level',NULL,NULL,'Permanent','None',NULL,'yes','Yes (object)'),
  ('dd-spell-maddening-scream','dd-3.0','217','maddening-scream','Maddening Scream','Drive a living creature into uncontrollable screaming and movement, preventing normal actions, worsening Armor Class, severely limiting Reflex saves, and preventing shield use.','phb-spell-school-enchantment','Compulsion','1 standard action','standard','Touch','Living creature touched',NULL,NULL,'1d4+1 rounds','None',NULL,'yes','Yes'),
  ('dd-spell-surelife','dd-3.0','217','surelife','Surelife','Choose one natural condition that would ordinarily be deadly; for the spell''s duration the caster suffers no discomfort or damage from that specified condition, but the protection does not cover spells, creature attacks, or carried items.','phb-spell-school-abjuration',NULL,'1 round','other','Personal','You',NULL,NULL,'1 minute/2 levels','None',NULL,'no','No'),
  ('dd-spell-touch-of-madness','dd-3.0','217','touch-of-madness','Touch of Madness','A successful touch can daze one living creature for 1 round per caster level on a failed Will save.','phb-spell-school-enchantment',NULL,'1 standard action','standard','Touch','Creature touched',NULL,NULL,'1 round/level','Will negates','will','yes','Yes'),
  ('dd-spell-true-creation','dd-3.0','217-218','true-creation','True Creation','Create a permanent unattended nonmagical object of nonliving matter; complex objects require the appropriate Craft check, and created matter is real enough to serve as material components.','phb-spell-school-conjuration','Creation','10 minutes','other','0 ft.',NULL,NULL,'Unattended nonmagical object of nonliving matter, up to 1 cu. ft./level','Instantaneous','None',NULL,'no','No'),
  ('dd35-spell-status-greater','dd-3.5-update','update 6','status-greater','Status, Greater','Functions as status for multiple touched allies and additionally allows the caster to deliver qualifying harmless 0th- through 2nd-level touch spells through the established link.','phb-spell-school-divination',NULL,'1 standard action','standard','Touch','One creature touched/three levels',NULL,NULL,'1 hour/level','Will negates (harmless)','will','yes','Yes (harmless)')
)
INSERT INTO dnd35_spells
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,school_id,subschool,casting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,saving_throw_text,save,spell_resistance,spell_resistance_text)
SELECT d.id,d.source_id,d.page,d.slug,d.name,d.summary,d.summary,0,NULL,1,d.school_id,d.subschool,d.casting_time,d.action_type,d.range_text,d.target_text,d.area_text,d.effect_text,d.duration_text,d.saving_throw_text,d.save,d.spell_resistance,d.spell_resistance_text
FROM desired d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_spells s WHERE s.slug=d.slug AND s.owner_user_id IS NULL);
